//! @generated by xtask split-potions.
use super::prelude::*;

/// TouchOfInsanity — choose one cost-bearing card in hand and make it
/// free (cost 0) for the rest of combat. C# TouchOfInsanity.OnUse:
/// `CardSelectCmd.FromHand(prefs(1), filter: CostsEnergyOrStars)` →
/// `.FirstOrDefault()?.SetToFreeThisCombat()` — a player choice (single
/// pick) over the cost-bearing hand cards. Bead `sts2-rs-1xmxp` (closing
/// `sts2-rs-gbaft`) replaces the prior uniform-random pick (the
/// `NOTE(sts2-rs-sr3ql)` legacy-rng caveat is now resolved).
///
/// `star_cost` is not yet a `Card` field, so the candidate filter gates
/// on `cost > 0` only — a strict subset of C#'s `CostsEnergyOrStars`
/// (no false positives). FirstOrDefault precedent: 0 candidates → no-op;
/// exactly 1 → set it free directly (no prompt); 2+ → open a single-pick
/// `MakeFreeInHand` choice. The resolver sets the chosen in-combat
/// card's `cost` to 0, which lasts only this combat (per-combat
/// `CombatState.cards` scratch — same lifetime as `SetToFreeThisCombat`).
pub(crate) fn drink_touch_of_insanity(
    state: &mut CombatState,
    _target: Option<u8>,
) -> EffectResult {
    let candidates: smallvec::SmallVec<[sts2_core::CardUid; 10]> = state
        .player
        .hand
        .iter()
        .copied()
        .filter(|uid| {
            let idx = uid.0.get() as usize - 1;
            let c = &state.cards[idx];
            // C# `CostsEnergyOrStars` resolves cost WITH local modifiers
            // (`CardEnergyCost.GetWithModifiers`): a LiquidMemories /
            // potion-generated free-this-turn card already costs 0 and is
            // filtered OUT — C#'s TOI no-ops on it (sweep seed 3991: Rust
            // selected the free RAMPAGE+1 off raw `cost > 0` and made it
            // free for the whole combat). The raw cost stays as a guard so
            // X-cost (-1) cards remain excluded.
            if c.combat_var(sts2_core::cards::VarKey::FreeThisTurn) != 0 {
                return false;
            }
            // C# filters on `CostsEnergyOrStars` — energy OR stars. A Regent
            // 0-energy star card (FallingStar / Quasar, or a Confused-to-0
            // DyingStar) still costs STARS, so it IS a valid target. Mirror
            // both halves: raw energy cost > 0, or a positive star cost.
            // `effective_star_cost` returns 0 once a card is already free
            // (StarCostFreeThisCombat) so it won't be re-selected.
            // `CostsEnergyOrStars(false) || CostsEnergyOrStars(true)`: the cost
            // with its local modifiers, or with the global ones too — not
            // the printed cost. A Flatten zeroed by an Osty attack is no
            // option (loadout Necrobinder 3159 v0.111.0: Rust offered it,
            // shifting the pick onto Mimic instead of Melancholy).
            let energy = c.cost >= 0
                && (sts2_core::hooks::local_card_cost(state, c) > 0
                    || sts2_core::hooks::effective_card_cost_inst(state, c, *uid) > 0);
            energy || sts2_core::effective_star_cost(c) > 0
        })
        .collect();
    match candidates.as_slice() {
        [] => {}
        [uid] => {
            // FirstOrDefault: a single cost-bearing card, set free directly.
            let idx = uid.0.get() as usize - 1;
            // C# `SetToFreeThisCombat` zeros the star cost too (a Regent star
            // card freed this way is playable regardless of stars).
            // C# `SetThisCombat(0)` is an *Absolute* local cost modifier — mark
            // it so a later in-combat cost-reducing upgrade clamps (stays 0)
            // instead of underflowing to -1 (an X-cost that drains all energy).
            // Mirrors the multi-pick `resolve_make_free_in_hand` resolver in
            // sts2-core. Bead `sts2-rs-2e9q2` (gh#180 CALAMITY).
            state.cards[idx].set_free_this_combat();
        }
        _ => {
            let options: Vec<sts2_core::ChoiceOption> = candidates
                .iter()
                .map(|&uid| {
                    let idx = uid.0.get() as usize - 1;
                    sts2_core::ChoiceOption {
                        card_id: state.cards[idx].card_id,
                        upgraded: state.cards[idx].upgraded,
                        card_uid: Some(uid),
                        source_pile: Some(sts2_core::cards::PileKind::Hand),
                    }
                })
                .collect();
            state.request_card_choice(sts2_core::ChoiceKind::MakeFreeInHand, options, 1, 1, false);
        }
    }
    EffectResult::Resolved
}
